package api.parking_space_p; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.security.core.Authentication; import java.util.List; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ParkingSpaceControllerTest { @Mock ParkingSpaceService service; @Mock Authentication auth; @InjectMocks ParkingSpaceController controller; @Test @DisplayName("UT-BE-PARKINGSPACE-CTRL-001 주차장 코드로 주차면을 조회한다") void list(){ List<ParkingSpaceDTO>x=List.of(); when(service.list("B1")).thenReturn(x); assertThat(controller.list("B1")).isSameAs(x); } @Test @DisplayName("UT-BE-PARKINGSPACE-CTRL-002 로그인 입주민 차량 위치를 조회한다") void mine(){ when(auth.getName()).thenReturn("user"); List<ParkingSpaceDTO>x=List.of(); when(service.myVehicleLocations("user")).thenReturn(x); assertThat(controller.myVehicleLocations(auth)).isSameAs(x); } }
